```c
#include <math.h>
#include <string.h>
#include <stdlib.h>

#define MAX_N 20

// Block power iteration
// Returns 1 if converged
int block_power_iter(const double *A, int n, double *eigval_real, double *eigval_imag,
                     double *vec_real, double *vec_imag, double tol, int max_iter) {
    // v1, v2 - two orthonormal vectors
    // w1, w2 - intermediate vectors
    double v1[MAX_N], v2[MAX_N], w1[MAX_N], w2[MAX_N];
    double tmp1[MAX_N], tmp2[MAX_N];
    double H[4];  // 2x2 matrix in column-major
    double dot, n1, n2;
    int converged = 0;

    // Initialize v1, v2
    for (int i = 0; i < n; i++) {
        v1[i] = 0.0;
        v2[i] = 0.0;
    }
    // Use A*1 and A^2*1 as initial vectors (then orthonormalize)
    // Compute A @ ones
    for (int i = 0; i < n; i++) {
        double s = 0;
        for (int j = 0; j < n; j++) s += A[i * n + j];
        v1[i] = s;
    }
    // Compute A @ v1
    for (int i = 0; i < n; i++) {
        double s = 0;
        for (int j = 0; j < n; j++) s += A[i * n + j] * v1[j];
        v2[i] = s;
    }
    // Normalize v1
    n1 = 0;
    for (int i = 0; i < n; i++) n1 += v1[i] * v1[i];
    n1 = sqrt(n1);
    for (int i = 0; i < n; i++) v1[i] /= n1;
    // Orthogonalize v2 against v1
    dot = 0;
    for (int i = 0; i < n; i++) dot += v2[i] * v1[i];
    for (int i = 0; i < n; i++) v2[i] -= dot * v1[i];
    n2 = 0;
    for (int i = 0; i < n; i++) n2 += v2[i] * v2[i];
    n2 = sqrt(n2);
    if (n2 < 1e-300) {
        // v2 was parallel to v1, use a different initial vector
        for (int i = 0; i < n; i++) v2[i] = (i == 0) ? 1.0 : 0.0;
        dot = v2[0] * v1[0];
        for (int i = 0; i < n; i++) v2[i] -= dot * v1[i];
        n2 = 0;
        for (int i = 0; i < n; i++) n2 += v2[i] * v2[i];
        n2 = sqrt(n2);
        if (n2 < 1e-300) {
            for (int i = 0; i < n; i++) v2[i] = (i == 1) ? 1.0 : 0.0;
        }
    }
    for (int i = 0; i < n; i++) v2[i] /= n2;

    // Power iteration
    for (int iter = 0; iter < max_iter; iter++) {
        // w1 = A @ v1, w2 = A @ v2
        for (int i = 0; i < n; i++) {
            double s1 = 0, s2 = 0;
            for (int j = 0; j < n; j++) {
                s1 += A[i * n + j] * v1[j];
                s2 += A[i * n + j] * v2[j];
            }
            w1[i] = s1;
            w2[i] = s2;
        }

        // Orthogonalize w1, w2 (modified Gram-Schmidt)
        // Normalize w1
        n1 = 0;
        for (int i = 0; i < n; i++) n1 += w1[i] * w1[i];
        n1 = sqrt(n1);
        if (n1 < 1e-300) break;
        for (int i = 0; i < n; i++) v1[i] = w1[i] / n1;
        // Orthogonalize w2 against v1
        dot = 0;
        for (int i = 0; i < n; i++) dot += w2[i] * v1[i];
        for (int i = 0; i < n; i++) tmp2[i] = w2[i] - dot * v1[i];
        n2 = 0;
        for (int i = 0; i < n; i++) n2 += tmp2[i] * tmp2[i];
        n2 = sqrt(n2);
        if (n2 < 1e-300) {
            // w2 is in the span of v1, perturb it
            for (int i = 0; i < n; i++) tmp2[i] = w2[i] + 0.1 * ((double)rand() / RAND_MAX - 0.5);
            // Re-orthogonalize
            dot = 0;
            for (int i = 0; i < n; i++) dot += tmp2[i] * v1[i];
            for (int i = 0; i < n; i++) tmp2[i] -= dot * v1[i];
            n2 = 0;
            for (int i = 0; i < n; i++) n2 += tmp2[i] * tmp2[i];
            n2 = sqrt(n2);
            if (n2 < 1e-300) break;
        }
        for (int i = 0; i < n; i++) v2[i] = tmp2[i] / n2;

        // Compute H = V^T A V (2x2)
        // H[0,0] = v1^T A v1
        // H[0,1] = v1^T A v2
        // H[1,0] = v2^T A v1
        // H[1,1] = v2^T A v2
        // We can use the w vectors: A v1 and A v2
        for (int i = 0; i < n; i++) {
            double s1 = 0, s2 = 0;
            for (int j = 0; j < n; j++) {
                s1 += A[i * n + j] * v1[j];
                s2 += A[i * n + j] * v2[j];
            }
            tmp1[i] = s1;  // A v1
            tmp2[i] = s2;  // A v2
        }
        H[0] = 0; H[1] = 0; H[2] = 0; H[3] = 0;
        for (int i = 0; i < n; i++) {
            H[0] += v1[i] * tmp1[i];
            H[1] += v2[i] * tmp1[i];  // H[1,0] = v2^T A v1
            H[2] += v1[i] * tmp2[i];  // H[0,1] = v1^T A v2
            H[3] += v2[i] * tmp2[i];
        }

        // Find eigenvalues of H
        // H = [[a, b], [c, d]] in column-major: H[0]=a, H[2]=b, H[1]=c, H[3]=d
        // Wait, let me clarify the storage:
        // I set H[0] += v1[i] * tmp1[i] = v1^T A v1 = H[0,0]
        // H[1] += v2[i] * tmp1[i] = v2^T A v1 = H[1,0]
        // H[2] += v1[i] * tmp2[i] = v1^T A v2 = H[0,1]
        // H[3] += v2[i] * tmp2[i] = v2^T A v2 = H[1,1]
        // So a = H[0], b = H[2], c = H[1], d = H[3]
        double a = H[0], b = H[2], c = H[1], d = H[3];
        double tr = a + d;
        double det = a * d - b * c;
        double disc = tr * tr - 4 * det;

        double e1_re, e1_im, e2_re, e2_im;
        if (disc >= 0) {
            double sq = sqrt(disc);
            e1_re = (tr + sq) / 2;
            e1_im = 0;
            e2_re = (tr - sq) / 2;
            e2_im = 0;
        } else {
            double sq = sqrt(-disc);
            e1_re = tr / 2;
            e1_im = sq / 2;
            e2_re = tr / 2;
            e2_im = -sq / 2;
        }

        // Pick the dominant one
        double m1 = e1_re * e1_re + e1_im * e1_im;
        double m2 = e2_re * e2_re + e2_im * e2_im;
        if (m1 >= m2) {
            *eigval_real = e1_re;
            *eigval_imag = e1_im;
        } else {
            *eigval_real = e2_re;
            *eigval_imag = e2_im;
        }

        // Check convergence
        // Compare with previous iteration's eigenvalues
        // ... need to store previous eigenvalues

        // For now, just iterate a fixed number of times
    }

    // Final: compute the eigenvector
    // The dominant Ritz vector is u = alpha * v1 + beta * v2 where (H - λI) [alpha; beta] = 0
    // For real λ, beta = -(a - λ) * alpha / b, or alpha = -(d - λ) * beta / c
    // For complex λ, similar
    // ...
}
```

