```python
def find_dominant_eigenvalue_and_eigenvector(A):
    n = A.shape[0]
    # Faddeev-LeVerrier
    B = np.eye(n)
    c = np.zeros(n + 1)
    c[0] = 1.0
    c[1] = -np.trace(A)
    for k in range(2, n + 1):
        B = A @ B + c[k-1] * np.eye(n)
        c[k] = -np.trace(A @ B) / k
    # Find roots
    eigenvalues = np.roots(c[::-1])  # np.roots expects highest degree first
    # Pick dominant
    idx = np.argmax(np.abs(eigenvalues))
    lam = eigenvalues[idx]
    # Find eigenvector: solve (A - lam*I) v = 0
    M = A - lam * np.eye(n)
    _, _, Vt = np.linalg.svd(M)
    v = Vt[-1]
    # Normalize to unit norm
    v = v / np.linalg.norm(v)
    return lam, v
```

