#include <math.h>
#include <string.h>
#include <stdlib.h>

#define MAX_N 16

// Block power iteration
// A: n x n matrix (row-major)
// Returns 1 if converged (eigenvalue found)
// eigval_real, eigval_imag: real and imaginary parts of dominant eigenvalue
// vec_real, vec_imag: real and imaginary parts of corresponding eigenvector
int block_power_iter(const double *A, int n, double *eigval_real, double *eigval_imag,
                     double *vec_real, double *vec_imag, double tol, int max_iter) {
    // Use static arrays for speed
    double v1[MAX_N], v2[MAX_N], w1[MAX_N], w2[MAX_N], Av1[MAX_N], Av2[MAX_N], t1[MAX_N], t2[MAX_N];
    double dot, n1, n2;
    int iter;

    // Initialize v1, v2
    // Use A * 1 and A^2 * 1 as initial vectors
    for (int i = 0; i < n; i++) {
        double s = 0;
        for (int j = 0; j < n; j++) s += A[i * n + j];
        v1[i] = s;
    }
    for (int i = 0; i < n; i++) {
        double s = 0;
        for (int j = 0; j < n; j++) s += A[i * n + j] * v1[j];
        v2[i] = s;
    }
    // Normalize v1
    n1 = 0;
    for (int i = 0; i < n; i++) n1 += v1[i] * v1[i];
    n1 = sqrt(n1);
    if (n1 < 1e-300) {
        // Use a different initial vector
        v1[0] = 1.0;
        for (int i = 1; i < n; i++) v1[i] = 0.0;
        n1 = 1.0;
    }
    for (int i = 0; i < n; i++) v1[i] /= n1;
    // Orthogonalize v2 against v1
    dot = 0;
    for (int i = 0; i < n; i++) dot += v2[i] * v1[i];
    for (int i = 0; i < n; i++) v2[i] -= dot * v1[i];
    n2 = 0;
    for (int i = 0; i < n; i++) n2 += v2[i] * v2[i];
    n2 = sqrt(n2);
    if (n2 < 1e-300) {
        // Use a different initial vector
        v2[1] = 1.0;
        for (int i = 0; i < n; i++) v2[i] = (i == 1) ? 1.0 : 0.0;
        dot = v2[0] * v1[0];
        for (int i = 1; i < n; i++) v2[i] = (i == 1) ? 1.0 - dot * v1[1] : -dot * v1[i];
        n2 = 0;
        for (int i = 0; i < n; i++) n2 += v2[i] * v2[i];
        n2 = sqrt(n2);
    }
    for (int i = 0; i < n; i++) v2[i] /= n2;

    // Iterate
    for (iter = 0; iter < max_iter; iter++) {
        // w1 = A @ v1, w2 = A @ v2
        for (int i = 0; i < n; i++) {
            double s1 = 0, s2 = 0;
            for (int j = 0; j < n; j++) {
                s1 += A[i * n + j] * v1[j];
                s2 += A[i * n + j] * v2[j];
            }
            w1[i] = s1;
            w2[i] = s2;
        }

        // Orthogonalize w1, w2 (modified Gram-Schmidt)
        // Normalize w1
        n1 = 0;
        for (int i = 0; i < n; i++) n1 += w1[i] * w1[i];
        n1 = sqrt(n1);
        if (n1 < 1e-300) {
            // Eigenvalue is 0
            *eigval_real = 0;
            *eigval_imag = 0;
            for (int i = 0; i < n; i++) vec_real[i] = v1[i];
            for (int i = 0; i < n; i++) vec_imag[i] = 0;
            return 1;
        }
        for (int i = 0; i < n; i++) v1[i] = w1[i] / n1;
        // Orthogonalize w2 against v1
        dot = 0;
        for (int i = 0; i < n; i++) dot += w2[i] * v1[i];
        for (int i = 0; i < n; i++) t1[i] = w2[i] - dot * v1[i];
        n2 = 0;
        for (int i = 0; i < n; i++) n2 += t1[i] * t1[i];
        n2 = sqrt(n2);
        if (n2 < 1e-300) {
            // w2 is parallel to v1, perturb
            for (int i = 0; i < n; i++) t1[i] = w2[i] + 0.01 * v1[(i+1) % n];
            dot = 0;
            for (int i = 0; i < n; i++) dot += t1[i] * v1[i];
            for (int i = 0; i < n; i++) t1[i] -= dot * v1[i];
            n2 = 0;
            for (int i = 0; i < n; i++) n2 += t1[i] * t1[i];
            n2 = sqrt(n2);
            if (n2 < 1e-300) continue;
        }
        for (int i = 0; i < n; i++) v2[i] = t1[i] / n2;

        // Compute H = V^T A V (2x2)
        // Av1 = A @ v1, Av2 = A @ v2
        for (int i = 0; i < n; i++) {
            double s1 = 0, s2 = 0;
            for (int j = 0; j < n; j++) {
                s1 += A[i * n + j] * v1[j];
                s2 += A[i * n + j] * v2[j];
            }
            Av1[i] = s1;
            Av2[i] = s2;
        }
        // H[0,0] = v1 . Av1
        // H[0,1] = v1 . Av2
        // H[1,0] = v2 . Av1
        // H[1,1] = v2 . Av2
        double h00 = 0, h01 = 0, h10 = 0, h11 = 0;
        for (int i = 0; i < n; i++) {
            h00 += v1[i] * Av1[i];
            h01 += v1[i] * Av2[i];
            h10 += v2[i] * Av1[i];
            h11 += v2[i] * Av2[i];
        }

        // Find eigenvalues of H
        double tr = h00 + h11;
        double det = h00 * h11 - h01 * h10;
        double disc = tr * tr - 4 * det;
        double e1_re, e1_im, e2_re, e2_im;
        if (disc >= 0) {
            double sq = sqrt(disc);
            e1_re = (tr + sq) / 2;
            e1_im = 0;
            e2_re = (tr - sq) / 2;
            e2_im = 0;
        } else {
            double sq = sqrt(-disc);
            e1_re = tr / 2;
            e1_im = sq / 2;
            e2_re = tr / 2;
            e2_im = -sq / 2;
        }

        // Pick the dominant one
        double m1 = e1_re * e1_re + e1_im * e1_im;
        double m2 = e2_re * e2_re + e2_im * e2_im;
        if (m1 >= m2) {
            *eigval_real = e1_re;
            *eigval_imag = e1_im;
            // Ritz vector: c2 = 1, c1 = -(h00 - λ) / h01 (if h01 != 0)
            // Or c1 = 1, c2 = -h01 / (h11 - λ)
            if (fabs(h01) > 1e-300) {
                double re = h00 - e1_re;
                double im = -e1_im;
