                double c1_re = -re / h01;
                double c1_im = -im / h01;
                // u = c1 * v1 + v2
                for (int i = 0; i < n; i++) {
                    vec_real[i] = c1_re * v1[i] + v2[i];
                    vec_imag[i] = c1_im * v1[i];
                }
            } else {
                // h01 is 0, use c1 = 1
                for (int i = 0; i < n; i++) {
                    vec_real[i] = v1[i];
                    vec_imag[i] = 0;
                }
            }
        } else {
            *eigval_real = e2_re;
            *eigval_imag = e2_im;
            if (fabs(h01) > 1e-300) {
                double re = h00 - e2_re;
                double im = -e2_im;
                double c1_re = -re / h01;
                double c1_im = -im / h01;
