#include <math.h>
#include <string.h>
#include <stdlib.h>

#define MAX_N 16

// Block power iteration
// Returns 1 on success
int find_dominant(const double *A, int n,
                  double *eigval_re, double *eigval_im,
                  double *vec_re, double *vec_im,
                  double tol, int max_iter) {
    double v1[MAX_N], v2[MAX_N], Av1[MAX_N], Av2[MAX_N], tmp[MAX_N];
    int iter;
    double n1, n2, dot, tr, det, disc, sq;
    double h00, h01, h10, h11;
    double e1_re, e1_im, e2_re, e2_im, m1, m2;
    double lam_re, lam_im, prev_re = 0, prev_im = 0;
    double diff, mag;
    int converged = 0;

    // Initialize v1, v2
    // Use (1, 1, ..., 1) and (1, -1, 1, -1, ...) as initial vectors
    for (int i = 0; i < n; i++) {
        v1[i] = 1.0;
        v2[i] = (i & 1) ? -1.0 : 1.0;
    }
    // Normalize v1
    n1 = 0;
    for (int i = 0; i < n; i++) n1 += v1[i] * v1[i];
    n1 = sqrt(n1);
    for (int i = 0; i < n; i++) v1[i] /= n1;
    // Orthogonalize v2 against v1
    dot = 0;
    for (int i = 0; i < n; i++) dot += v2[i] * v1[i];
    for (int i = 0; i < n; i++) v2[i] -= dot * v1[i];
    n2 = 0;
    for (int i = 0; i < n; i++) n2 += v2[i] * v2[i];
    n2 = sqrt(n2);
    for (int i = 0; i < n; i++) v2[i] /= n2;

    for (iter = 0; iter < max_iter; iter++) {
        // Compute Av1 = A @ v1, Av2 = A @ v2
        for (int i = 0; i < n; i++) {
            double s1 = 0, s2 = 0;
            for (int j = 0; j < n; j++) {
                s1 += A[i * n + j] * v1[j];
                s2 += A[i * n + j] * v2[j];
            }
            Av1[i] = s1;
            Av2[i] = s2;
        }

        // Normalize v1 = Av1 / |Av1|
        n1 = 0;
        for (int i = 0; i < n; i++) n1 += Av1[i] * Av1[i];
        n1 = sqrt(n1);
        if (n1 < 1e-300) {
            *eigval_re = 0; *eigval_im = 0;
            for (int i = 0; i < n; i++) { vec_re[i] = v1[i]; vec_im[i] = 0; }
            return 1;
        }
        for (int i = 0; i < n; i++) v1[i] = Av1[i] / n1;
        // Orthogonalize v2 = (Av2 - (Av2.v1) v1) / |.|
        dot = 0;
        for (int i = 0; i < n; i++) dot += Av2[i] * v1[i];
        for (int i = 0; i < n; i++) tmp[i] = Av2[i] - dot * v1[i];
        n2 = 0;
        for (int i = 0; i < n; i++) n2 += tmp[i] * tmp[i];
        n2 = sqrt(n2);
        if (n2 < 1e-300) {
            // Av2 is parallel to v1, add perturbation
            for (int i = 0; i < n; i++) tmp[i] = Av2[i] + v2[i] * 0.1;
            dot = 0;
            for (int i = 0; i < n; i++) dot += tmp[i] * v1[i];
            for (int i = 0; i < n; i++) tmp[i] -= dot * v1[i];
            n2 = 0;
            for (int i = 0; i < n; i++) n2 += tmp[i] * tmp[i];
            n2 = sqrt(n2);
            if (n2 < 1e-300) {
                // Total failure, restart with standard basis
                for (int i = 0; i < n; i++) {
                    v1[i] = (i == 0) ? 1.0 : 0.0;
                    v2[i] = (i == 1) ? 1.0 : 0.0;
                }
                continue;
            }
        }
        for (int i = 0; i < n; i++) v2[i] = tmp[i] / n2;

        // Compute H = V^T A V using new v1, v2
        for (int i = 0; i < n; i++) {
            double s1 = 0, s2 = 0;
            for (int j = 0; j < n; j++) {
                s1 += A[i * n + j] * v1[j];
                s2 += A[i * n + j] * v2[j];
            }
            Av1[i] = s1;
            Av2[i] = s2;
        }
        h00 = h01 = h10 = h11 = 0;
        for (int i = 0; i < n; i++) {
            h00 += v1[i] * Av1[i];
            h01 += v1[i] * Av2[i];
            h10 += v2[i] * Av1[i];
            h11 += v2[i] * Av2[i];
        }

        // Eigenvalues of H
        tr = h00 + h11;
        det = h00 * h11 - h01 * h10;
        disc = tr * tr - 4 * det;
        if (disc >= 0) {
            sq = sqrt(disc);
            e1_re = (tr + sq) / 2; e1_im = 0;
            e2_re = (tr - sq) / 2; e2_im = 0;
        } else {
            sq = sqrt(-disc);
            e1_re = tr / 2; e1_im = sq / 2;
            e2_re = tr / 2; e2_im = -sq / 2;
        }
        m1 = e1_re * e1_re + e1_im * e1_im;
        m2 = e2_re * e2_re + e2_im * e2_im;
        if (m1 >= m2) {
            lam_re = e1_re; lam_im = e1_im;
        } else {
            lam_re = e2_re; lam_im = e2_im;
        }

        // Check convergence
        if (iter > 0) {
            diff = (lam_re - prev_re) * (lam_re - prev_re) + (lam_im - prev_im) * (lam_im - prev_im);
            diff = sqrt(diff);
            mag = sqrt(lam_re * lam_re + lam_im * lam_im);
            if (mag > 1e-300 && diff / mag < tol) {
                converged = 1;
            }
        }
        prev_re = lam_re;
        prev_im = lam_im;

        // Compute Ritz vector
        // (H - λI) c = 0
        // (h00 - λ) c1 + h01 c2 = 0
        // h10 c1 + (h11 - λ) c2 = 0
        // Use the more stable equation
        double re1 = h00 - lam_re, im1 = -lam_im;
        double re2 = h11 - lam_re, im2 = -lam_im;
        double mag1 = sqrt(re1 * re1 + im1 * im1);
        double mag2 = sqrt(re2 * re2 + im2 * im2);
        double c1_re, c1_im, c2_re, c2_im, denom;
        if (mag1 >= mag2 && mag1 > 1e-300) {
            // c2 = 1, c1 = -h01 / (h00 - λ)
            denom = re1 * re1 + im1 * im1;
            c1_re = -h01 * re1 / denom;
            c1_im = h01 * im1 / denom;
            c2_re = 1.0; c2_im = 0.0;
        } else if (mag2 > 1e-300) {
            // c1 = 1, c2 = -h10 / (h11 - λ)
            denom = re2 * re2 + im2 * im2;
            c2_re = -h10 * re2 / denom;
            c2_im = h10 * im2 / denom;
            c1_re = 1.0; c1_im = 0.0;
        } else {
            c1_re = 1.0; c1_im = 0.0;
            c2_re = 0.0; c2_im = 0.0;
        }

        for (int i = 0; i < n; i++) {
            vec_re[i] = c1_re * v1[i] + c2_re * v2[i];
            vec_im[i] = c1_im * v1[i] + c2_im * v2[i];
        }

        *eigval_re = lam_re;
        *eigval_im = lam_im;

        if (converged) return 1;
    }

    return 1;
}
